def bank_balance_overdraft(events, overdraft_limit):
    balance = 0
    for op, amount in events:
        if op == "deposit":
            balance += amount
        elif op == "withdraw":
            if balance - amount >= -overdraft_limit:
                balance -= amount
    return balance

def inventory_counts(events):
    counts = {}
    for item, delta in events:
        if item not in counts:
            counts[item] = 0
        new_val = counts[item] + delta
        if new_val >= 0:
            counts[item] = new_val
    return counts

def elevator_floor(start_floor, commands, min_floor, max_floor):
    floor = start_floor
    for c in commands:
        if c == "UP":
            floor = min(floor + 1, max_floor)
        elif c == "DOWN":
            floor = max(floor - 1, min_floor)
    return floor

def traffic_light_state(n_ticks, durations):
    red, green, yellow = durations
    cycle = red + green + yellow
    pos = n_ticks % cycle
    if pos < red:
        return "RED"
    elif pos < red + green:
        return "GREEN"
    else:
        return "YELLOW"

def turnstile_state(events):
    state = "LOCKED"
    for e in events:
        if e == "coin":
            state = "UNLOCKED"
        elif e == "push":
            if state == "UNLOCKED":
                state = "LOCKED"
    return state

def queue_simulation(commands):
    queue = []
    for cmd in commands:
        if cmd[0] == "enqueue":
            queue.append(cmd[1])
        elif cmd[0] == "dequeue":
            if queue:
                queue.pop(0)
    return queue

def robot_grid_position(commands):
    x, y = 0, 0
    facing = "N"
    left_turn = {"N": "W", "W": "S", "S": "E", "E": "N"}
    right_turn = {"N": "E", "E": "S", "S": "W", "W": "N"}
    moves = {"N": (0, 1), "S": (0, -1), "E": (1, 0), "W": (-1, 0)}
    for c in commands:
        if c == "L":
            facing = left_turn[facing]
        elif c == "R":
            facing = right_turn[facing]
        elif c == "F":
            dx, dy = moves[facing]
            x += dx
            y += dy
    return (x, y, facing)

def vending_machine_credit(events):
    credit = 0
    dispensed = 0
    for op, val in events:
        if op == "insert":
            credit += val
        elif op == "select":
            if val <= credit:
                credit -= val
                dispensed += 1
    return (credit, dispensed)

def parking_lot_occupancy(events, capacity):
    occupied = set()
    for op, spot in events:
        if op == "enter":
            if len(occupied) < capacity and spot not in occupied:
                occupied.add(spot)
        elif op == "exit":
            occupied.discard(spot)
    return sorted(occupied)

def game_score_tally(events):
    score = 0
    for e in events:
        if e[0] == "score":
            score += e[1]
        elif e[0] == "bonus":
            score *= 2
        elif e[0] == "penalty":
            score = max(0, score - e[1])
    return score

def thermostat_mode(events, initial_target):
    target = initial_target
    mode = "IDLE"
    for op, val in events:
        if op == "set_target":
            target = val
        elif op == "read":
            if val < target:
                mode = "HEAT"
            elif val > target:
                mode = "COOL"
            else:
                mode = "IDLE"
    return mode

def library_checkout_status(events):
    checked_out = set()
    for op, book in events:
        if op == "checkout":
            if book not in checked_out:
                checked_out.add(book)
        elif op == "return":
            checked_out.discard(book)
    return sorted(checked_out)

def washing_machine_state(events):
    state = "OFF"
    for e in events:
        if e == "start" and state == "OFF":
            state = "RUNNING"
        elif e == "pause" and state == "RUNNING":
            state = "PAUSED"
        elif e == "resume" and state == "PAUSED":
            state = "RUNNING"
        elif e == "stop" and state in ("RUNNING", "PAUSED"):
            state = "OFF"
    return state

def rate_limiter_allowed(timestamps, limit, window):
    results = []
    for i, t in enumerate(timestamps):
        count = 0
        for j in range(i + 1):
            if timestamps[j] > t - window and timestamps[j] <= t:
                count += 1
        results.append(count <= limit)
    return results

def door_lock_state(events):
    state = "CLOSED"
    for e in events:
        if e == "lock" and state == "CLOSED":
            state = "LOCKED"
        elif e == "unlock" and state == "LOCKED":
            state = "CLOSED"
        elif e == "open" and state == "CLOSED":
            state = "OPEN"
        elif e == "close" and state == "OPEN":
            state = "CLOSED"
    return state

def two_player_score(events):
    p1 = 0
    p2 = 0
    for player, pts in events:
        if player == "P1":
            p1 = max(0, p1 + pts)
        elif player == "P2":
            p2 = max(0, p2 + pts)
    return (p1, p2)

def traffic_light_log(n_ticks, durations):
    red, green, yellow = durations
    cycle = red + green + yellow
    log = []
    for t in range(n_ticks):
        pos = t % cycle
        if pos < red:
            log.append("RED")
        elif pos < red + green:
            log.append("GREEN")
        else:
            log.append("YELLOW")
    return log

def multi_account_balances(events):
    balances = {}
    def ensure(acct):
        if acct not in balances:
            balances[acct] = 0
    for event in events:
        if event[0] == "deposit":
            _, acct, amt = event
            ensure(acct)
            balances[acct] += amt
        elif event[0] == "withdraw":
            _, acct, amt = event
            ensure(acct)
            if balances[acct] >= amt:
                balances[acct] -= amt
        elif event[0] == "transfer":
            _, frm, to, amt = event
            ensure(frm)
            ensure(to)
            if balances[frm] >= amt:
                balances[frm] -= amt
                balances[to] += amt
    return balances

def intersection_car_pass_count(events, green_duration):
    period = 2 * green_duration
    count = 0
    for tick, direction in events:
        pos = tick % period
        ns_green = pos < green_duration
        if direction in ("N", "S"):
            if ns_green:
                count += 1
        else:
            if not ns_green:
                count += 1
    return count
